import React, { useState, useEffect } from "react";
import "./ViewTasks.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import StudentSidebar from "../components/StudentSidebar";
import axios from "axios";

const ViewTasks = () => {
  const user = JSON.parse(localStorage.getItem('users'));
  const [milestones, setMilestones] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [group, setGroup] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // State for new inputs
  const [newMilestone, setNewMilestone] = useState({
    title: "",
    dueDate: "",
    status: "Pending"
  });

  const [newTask, setNewTask] = useState({
    title: "",
    status: "Pending",
    uploadedBy: user?.username || ""
  });

  // Fetch group data and related milestones/tasks
  useEffect(() => {
    const fetchData = async () => {
      try {
        if (!user || user.role !== "Student") {
          setError("Only students can access this page");
          setLoading(false);
          return;
        }

        // Check if student is in a group
        const studentRes = await axios.get(`http://localhost:5000/api/student/user/${user.id}`);
        const student = studentRes.data;

        if (!student.isGrouped) {
          setError("You need to be in a group to view tasks and milestones");
          setLoading(false);
          return;
        }

        // Get group information
        const groupRes = await axios.post(`http://localhost:5000/api/group/student/`,student.regNo);
        const groupData = groupRes.data;
        setGroup(groupData);

        // Get milestones for the group's project
        const milestonesRes = await axios.get(`http://localhost:5000/api/milestone/project/${groupData.projectID}`);
        setMilestones(milestonesRes.data);

        // Get all tasks for these milestones
        const tasksPromises = milestonesRes.data.map(milestone => 
          axios.get(`http://localhost:5000/api/task/milestone/${milestone._id}`)
        );

        const tasksResults = await Promise.all(tasksPromises);
        const allTasks = tasksResults.flatMap(res => res.data);
        setTasks(allTasks);

      } catch (err) {
        setError(err.response?.data?.message || "Failed to fetch data");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [user]);

  // Add new milestone
  const handleAddMilestone = async () => {
    if (!newMilestone.title.trim() || !newMilestone.dueDate) {
      alert("Please fill in all milestone fields.");
      return;
    }

    try {
      const milestoneData = {
        ...newMilestone,
        projectID: group.projectID
      };

      const res = await axios.post("http://localhost:5000/api/milestone", milestoneData);
      setMilestones([...milestones, res.data]);
      setNewMilestone({
        title: "",
        dueDate: "",
        status: "Pending"
      });
    } catch (err) {
      alert(err.response?.data?.message || "Failed to add milestone");
    }
  };

  // Add new task
  const handleAddTask = async (milestoneId) => {
    if (!newTask.title.trim()) {
      alert("Please enter a task title.");
      return;
    }

    try {
      const taskData = {
        ...newTask,
        milestoneId,
        uploadedBy: user.username
      };

      const res = await axios.post("http://localhost:5000/api/task", taskData);
      setTasks([...tasks, res.data]);
      setNewTask({
        title: "",
        status: "Pending",
        uploadedBy: user.username
      });
    } catch (err) {
      alert(err.response?.data?.message || "Failed to add task");
    }
  };

  // Update task status
  const handleUpdateTaskStatus = async (taskId, newStatus) => {
    try {
      const res = await axios.patch(`http://localhost:5000/api/task/${taskId}`, {
        status: newStatus,
        completedBy: user.username
      });

      setTasks(tasks.map(task => 
        task._id === taskId ? res.data : task
      ));
    } catch (err) {
      alert(err.response?.data?.message || "Failed to update task");
    }
  };

  const renderContent = () => {
    if (loading) {
      return <div className="loading-message">Loading...</div>;
    }

    if (error) {
      return <div className="error-message">{error}</div>;
    }

    if (!group) {
      return (
        <div className="group-warning">
          <h2>Group Required</h2>
          <p>You are not in any group yet. Please join a group to view tasks and milestones.</p>
        </div>
      );
    }

    return (
      <>
        <h1 className="tasks-title">Manage Milestones and Tasks</h1>

        {/* Input Field for Adding a Milestone */}
        <div className="milestone-section">
          <input
            type="text"
            value={newMilestone.title}
            onChange={(e) => setNewMilestone({...newMilestone, title: e.target.value})}
            placeholder="Milestone title"
          />
          <input
            type="date"
            value={newMilestone.dueDate}
            onChange={(e) => setNewMilestone({...newMilestone, dueDate: e.target.value})}
            placeholder="Due date"
          />
          <button onClick={handleAddMilestone}>Add Milestone</button>
        </div>

        {/* List of Milestones with Tasks */}
        <div className="milestone-list">
          {milestones.length > 0 ? (
            milestones.map((milestone) => (
              <div key={milestone._id} className="milestone-item">
                <h2>{milestone.title}</h2>
                <p>Due Date: {new Date(milestone.dueDate).toLocaleDateString()}</p>
                <p>Status: {milestone.status}</p>

                {/* Input Fields for Adding a Task to the Milestone */}
                <div className="task-section">
                  <input
                    type="text"
                    value={newTask.title}
                    onChange={(e) => setNewTask({...newTask, title: e.target.value})}
                    placeholder="Task title"
                  />
                  <button className="task-button" onClick={() => handleAddTask(milestone._id)}>
                    Add Task
                  </button>

                  {/* Table of Tasks Under the Milestone */}
                  <div className="tasks-table">
                    <table>
                      <thead>
                        <tr>
                          <th>Task</th>
                          <th>Uploaded By</th>
                          <th>Status</th>
                          <th>Completed By</th>
                          <th>Created At</th>
                          <th>Actions</th>
                        </tr>
                      </thead>
                      <tbody>
                        {tasks
                          .filter(task => task.milestoneId === milestone._id)
                          .map((task) => (
                            <tr key={task._id}>
                              <td>{task.title}</td>
                              <td>{task.uploadedBy}</td>
                              <td>{task.status}</td>
                              <td>{task.completedBy || "N/A"}</td>
                              <td>{new Date(task.createdAt).toLocaleString()}</td>
                              <td>
                                {task.status !== "Completed" && (
                                  <button
                                    className="mark-completed-button"
                                    onClick={() => handleUpdateTaskStatus(task._id, "Completed")}
                                  >
                                    Mark as Completed
                                  </button>
                                )}
                              </td>
                            </tr>
                          ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            ))
          ) : (
            <div className="no-milestones">
              <p>No milestones found for your project.</p>
            </div>
          )}
        </div>
      </>
    );
  };

  return (
    <div className="tasks-container">
      <Navbar />
      <div className="content-wrapper">
        <StudentSidebar />
        <div className="main-content">
          {renderContent()}
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewTasks;
